/**
 * Redaction of a frozen bug-report buffer before review and upload (spec package 3, §5).
 *
 * Import this module lazily, when a report is opened: it is the entry point of its own chunk,
 * and the worker it starts is another. `redactBuffer` runs the pass in a Web Worker kept for
 * the page's lifetime (click-to-redact re-runs it); `disposeRedactionWorker` ends it. Where
 * there is no `Worker` (Jest, jsdom) it runs on the main thread instead.
 */
import type { FrozenBuffer } from "../types";
import type { RedactionResult, RedactOptions } from "./types";
import type { WorkerRequest, WorkerResponse } from "./worker";

export type {
  Detector,
  RedactionResult,
  RedactionStats,
  RedactOptions,
  RemainingKind,
  RemainingString,
  Span,
  TaintSnapshot
} from "./types";
export { taintSnapshot } from "./taintSnapshot";

type Pending = { resolve: (r: RedactionResult) => void; reject: (e: Error) => void };

let worker: Worker | undefined;
let nextId = 0;
const pending = new Map<number, Pending>();

function failAll(error: Error): void {
  for (const p of pending.values()) p.reject(error);
  pending.clear();
}

async function getWorker(): Promise<Worker> {
  if (worker) return worker;
  const { spawnRedactionWorker } = await import("./spawnWorker");
  if (worker) return worker;
  const w = spawnRedactionWorker();
  w.onmessage = (event: MessageEvent<WorkerResponse>) => {
    const response = event.data;
    const p = pending.get(response.id);
    if (!p) return;
    pending.delete(response.id);
    if (response.ok) p.resolve(response.result);
    else p.reject(new Error(`Redaction failed: ${response.error}`));
  };
  w.onerror = (event: ErrorEvent) => {
    // A worker that failed to load or crashed can't answer; start a fresh one next time.
    event.preventDefault();
    if (worker === w) worker = undefined;
    w.terminate();
    failAll(new Error(`Redaction worker error: ${event.message || "failed to load"}`));
  };
  // A reply that can't be read carries no id to settle, and a pass left pending holds up Submit.
  w.onmessageerror = () => {
    if (worker === w) worker = undefined;
    w.terminate();
    failAll(new Error("Redaction worker sent an unreadable reply"));
  };
  worker = w;
  return w;
}

function copy<T>(value: T): T {
  return typeof structuredClone === "function" ? structuredClone(value) : (JSON.parse(JSON.stringify(value)) as T);
}

/**
 * Redacts a frozen buffer: trims it to `keepLastMs`, masks every detector hit, and lists the
 * strings left for review. `buffer` is not modified; the result holds a redacted copy.
 */
export async function redactBuffer(buffer: FrozenBuffer, opts: RedactOptions): Promise<RedactionResult> {
  if (typeof Worker === "undefined") {
    const { redactOwnedBuffer } = await import("./redact");
    return redactOwnedBuffer(copy(buffer), opts);
  }
  const w = await getWorker();
  return new Promise<RedactionResult>((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    const request: WorkerRequest = { id, buffer, opts };
    try {
      w.postMessage(request);
    } catch (err) {
      pending.delete(id);
      reject(err instanceof Error ? err : new Error(String(err)));
    }
  });
}

/** Ends the worker, failing any pass still running. The next `redactBuffer` starts a new one. */
export function disposeRedactionWorker(): void {
  const w = worker;
  worker = undefined;
  w?.terminate();
  failAll(new Error("Redaction worker disposed"));
}
/**
 * Types of the bug reporter's redaction pass (spec package 3). Type-only; see `./index.ts` for
 * `redactBuffer`.
 */
import type { FrozenBuffer } from "../types";
import type { TaintKind } from "../taint";

/**
 * The taint set in a form that can cross into the worker: every normalized match pattern
 * (`matchPatterns` variants) with the kind it came from.
 */
export type TaintSnapshot = { kind: TaintKind; pattern: string }[];

export type RedactOptions = {
  taintPatterns: TaintSnapshot;
  /**
   * Strings the user picked in review (click-to-redact), matched exactly, every occurrence. A
   * `*` in one matches any single non-space character, so a string copied from `remaining`
   * (where earlier redactions already show as `*`) still finds the original text.
   */
  extraRedactions?: string[];
  /**
   * Keep only the last this-many milliseconds. Whole segments are dropped from the front, so
   * the result still starts with Meta + FullSnapshot and spans at most this long (at least the
   * newest segment is always kept).
   */
  keepLastMs?: number;
};

export type RemainingKind = "text" | "attribute" | "input" | "console" | "breadcrumb" | "url" | "title";

/** A human-readable string still in the upload after redaction, for the review list (E2). */
export type RemainingString = { value: string; kind: RemainingKind; count: number };

export type RedactionStats = {
  /** Text nodes (and text changes) the walker looked at. */
  textNodes: number;
  /** Ranges replaced by mask characters, after merging overlapping detector spans. */
  redactedSpans: number;
  /** Wall time of the pass, in milliseconds. */
  ms: number;
};

export type RedactionResult = {
  /** A redacted deep copy; the input buffer is never modified. */
  buffer: FrozenBuffer;
  /** Grouped by kind, then most frequent first. Never holds a string made only of mask characters. */
  remaining: RemainingString[];
  stats: RedactionStats;
};

/** Half-open `[start, end)` range of the text a detector was given. */
export type Span = { start: number; end: number; kind: string };

/**
 * One stage of the detector chain: taint set, then the regex backstop, then the model if
 * package 4 ships. Async so a model can run on the GPU or in WASM.
 */
export type Detector = (text: string) => Promise<Span[]>;
/**
 * Synchronous redaction of one URL, for the page URL that the feedback event carries. The
 * replay's URLs go through the walker; the feedback is sent from the main bundle, so this
 * stays small: the taint set and the regex backstop over the same views of the URL as the
 * walker's (`urlViews`), no worker.
 */
import { MIN_MATCH_LENGTH, normalizeForMatch } from "../ahoCorasick";
import { getTaintSet, type TaintSet } from "../taint";
import { backstopDetector, maskRanges, mergeSpans, type SyncDetector } from "./detectors";
import { taintSnapshot } from "./taintSnapshot";
import type { Span, TaintSnapshot } from "./types";
import { toEncodedRange, urlViews } from "./urlText";

/**
 * The taint set's matches in a few short strings, found by looking each pattern up in the
 * normalized text directly. Building the Aho-Corasick automaton over a full taint set (up to
 * hundreds of thousands of patterns) takes seconds and hundreds of megabytes on the main thread.
 * This takes milliseconds per URL. The patterns are normalized already (`TaintSet.values()`), so
 * the spans are the ones the automaton finds.
 */
function scanDetector(patterns: TaintSnapshot): SyncDetector {
  return (input) => {
    const { text, starts, ends } = normalizeForMatch(input);
    const spans: Span[] = [];
    for (const { kind, pattern } of patterns) {
      if (pattern.length > text.length || pattern.trim().length < MIN_MATCH_LENGTH) continue;
      for (let i = text.indexOf(pattern); i !== -1; i = text.indexOf(pattern, i + 1)) {
        spans.push({ start: starts[i], end: ends[i + pattern.length - 1], kind });
      }
    }
    return spans;
  };
}

/** `url` with every taint or backstop hit (matched raw and percent-decoded) masked with `*`. */
export function redactReportUrl(url: string, set: TaintSet = getTaintSet()): string {
  const taint = scanDetector(taintSnapshot(set));
  const ranges: { start: number; end: number }[] = [];
  for (const view of urlViews(url)) {
    for (const d of view.exact ? [taint] : [taint, backstopDetector]) {
      for (const s of d(view.text)) {
        const [start, end] = view.map ? toEncodedRange(view.map, s.start, s.end) : [s.start, s.end];
        ranges.push({ start, end });
      }
    }
  }
  return ranges.length === 0 ? url : maskRanges(url, mergeSpans(ranges));
}
/**
 * E2E-only hook for the leak tests (D tests): `window.__bugReportRedaction`. It freezes the
 * running recorder, redacts the copy in the worker, and returns what the report would upload.
 *
 * Loaded only from `lib/bugReport/recorder.ts` inside `process.env.BUG_REPORT_E2E === "true"`,
 * a build-time constant (next.config.ts), so production bundles never contain it.
 */
import { getActiveRecorder } from "../activeRecorder";
import { buildReportTags } from "../submitFeedback";
import { redactBuffer, taintSnapshot, type RedactionResult } from "./index";
import { redactReportUrl } from "./reportUrl";

export type RedactionTestOptions = { extraRedactions?: string[]; keepLastMs?: number; description?: string };

export type RedactionTestHook = {
  /** Freeze and redact; the full result, for assertions on `remaining` and `stats`. */
  redact(
    options?: RedactionTestOptions
  ): Promise<RedactionResult & { worker: boolean; freezeMs: number; totalMs: number; events: number }>;
  /**
   * The bytes a report would upload, as a JSON string: the redacted events, the replay event
   * fields that come from the buffer, and the feedback payload.
   */
  uploadJson(options?: RedactionTestOptions): Promise<string>;
  /** Timings and sizes only, for measurements on big buffers. */
  measure(options?: RedactionTestOptions): Promise<RedactionMeasurement>;
};

export type RedactionMeasurement = {
  stats: RedactionResult["stats"];
  freezeMs: number;
  /** Freeze, post to the worker, redact, and receive the result. */
  totalMs: number;
  events: number;
  segments: number;
  /** Characters of event JSON in the redacted buffer. */
  size: number;
  remaining: number;
  worker: boolean;
};

declare global {
  interface Window {
    __bugReportRedaction?: RedactionTestHook;
  }
}

async function redact(options: RedactionTestOptions = {}) {
  const recorder = getActiveRecorder();
  if (!recorder) throw new Error("no recorder running");
  const t0 = performance.now();
  const frozen = recorder.freeze();
  const freezeMs = performance.now() - t0;
  const result = await redactBuffer(frozen, {
    taintPatterns: taintSnapshot(),
    extraRedactions: options.extraRedactions,
    keepLastMs: options.keepLastMs
  });
  const totalMs = performance.now() - t0;
  const events = result.buffer.segments.reduce((n, s) => n + s.events.length, 0);
  return { ...result, worker: typeof Worker !== "undefined", freezeMs, totalMs, events };
}

export function installRedactionTestHook(): void {
  window.__bugReportRedaction = {
    redact,
    async measure(options = {}) {
      const r = await redact(options);
      return {
        stats: r.stats,
        freezeMs: r.freezeMs,
        totalMs: r.totalMs,
        events: r.events,
        segments: r.buffer.segments.length,
        size: r.buffer.size,
        remaining: r.remaining.length,
        worker: r.worker
      };
    },
    async uploadJson(options = {}) {
      const { buffer } = await redact(options);
      return JSON.stringify({
        replay_event: {
          replay_id: buffer.replayId,
          urls: buffer.urls,
          error_ids: buffer.errorIds,
          trace_ids: buffer.traceIds
        },
        recording: buffer.segments.map((s) => s.events),
        feedback: {
          message: options.description ?? "Something went wrong",
          url: redactReportUrl(window.location.href),
          tags: buildReportTags({ contactOk: false })
        }
      });
    }
  };
}
/**
 * The redaction Web Worker. `redactBuffer` (./index.ts) starts it on the first report and keeps
 * it for re-runs (click-to-redact, keep-last-N changes). Each message is one pass over a copy
 * of the frozen buffer; the structured clone of `postMessage` is that copy.
 */
import type { FrozenBuffer } from "../types";
import { redactOwnedBuffer } from "./redact";
import type { RedactOptions } from "./types";

export type WorkerRequest = { id: number; buffer: FrozenBuffer; opts: RedactOptions };
export type WorkerResponse =
  | { id: number; ok: true; result: Awaited<ReturnType<typeof redactOwnedBuffer>> }
  | { id: number; ok: false; error: string };

// Typed by hand: the project compiles with the DOM lib, which conflicts with the webworker one.
const scope = self as unknown as {
  onmessage: ((event: MessageEvent<WorkerRequest>) => void) | null;
  postMessage(message: WorkerResponse): void;
};

const failure = (id: number, err: unknown): WorkerResponse => ({
  id,
  ok: false,
  error: err instanceof Error ? err.message : String(err)
});

scope.onmessage = async (event: MessageEvent<WorkerRequest>) => {
  const { id, buffer, opts } = event.data;
  let response: WorkerResponse;
  try {
    response = { id, ok: true, result: await redactOwnedBuffer(buffer, opts) };
  } catch (err) {
    response = failure(id, err);
  }
  try {
    scope.postMessage(response);
  } catch (err) {
    // A result that can't be sent still answers the pass, so `redactBuffer` doesn't wait forever.
    scope.postMessage(failure(id, err));
  }
};

